@Controller()
export class InvoiceMicroserviceController {
  constructor(
    @InjectRepository(Invoice)
    private readonly invoiceRepository: Repository<Invoice>,
  ) {}

  // Microservice RPC handler via TCP Transport
  @MessagePattern('billing.invoice.fetch')
  async getInvoice(@Payload() data: { invoiceId: string }) {
    // Queries invoice by ID directly from microservice payload
    const invoice = await this.invoiceRepository.findOne({
      where: { id: data.invoiceId },
      relations: ['lineItems', 'bankDetails', 'vendor'],
