import { Controller, UnauthorizedException, ForbiddenException } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Invoice } from '../entities/invoice.entity';

interface FetchInvoicePayload {
  invoiceId: string;
  requesterTenantId: string;
  requesterRole: string;
}

@Controller()
export class InvoiceMicroserviceController {
  constructor(
    @InjectRepository(Invoice)
    private readonly invoiceRepository: Repository<Invoice>,
  ) {}

  @MessagePattern('billing.invoice.fetch')
  async getInvoice(@Payload() data: FetchInvoicePayload) {
    if (!data.requesterTenantId) {
      return { error: 'Missing tenant authentication context in payload', status: 401 };
    }

    // Enforce tenant boundary on invoice query
    const invoice = await this.invoiceRepository.findOne({
      where: {
        id: data.invoiceId,
        tenantId: data.requesterTenantId,
      },
      relations: ['lineItems', 'bankDetails', 'vendor'],
    });

    if (!invoice) {
      return { error: 'Invoice not found or access denied', status: 404 };
    }

    return { invoice };
  }
}
